  # create a new question
  def create
    @question = Question.new(question_params)
    @question.uid = current_user.id if current_user
    @question.nid = @question.nid || Node.next_nid
    @question.status = 1

    if @question.save
      flash[:notice] = 'Your question has been posted successfully.'
      redirect_to question_path(@question)
    else
      render 'new'
    end
  end

  # show a single question
  def show
    @question = Node.questions.find_by(nid: params[:id])
    if @question.nil?
      render_404
    else
      @answers = @question.answers.order('node.created ASC')
      @answer = Answer.new
      @answer.question = @question
      @question.increment!(:view_count)
      @title = @question.title
      set_sidebar
    end
  end

